const sys = (key: string, image: string, blurb?: string, alt?: string): ProfileModel => {
  const s = SYSTEMS_RU[key];
  return m(key, s.name, s.kind, blurb ?? s.blurb, s.specs, s.features, alt ?? s.alt, `gp-${image}`);
};

