const COMPARE = ['Вариант', 'Крепление', 'Стекло', 'Особенность', 'Для чего'];

interface RailingPage extends Omit<ProfileCategory, 'group' | 'path' | 'eyebrow' | 'heroImage' | 'imageBase' | 'process' | 'compareColumns' | 'faq'> {
  path?: string;
  eyebrow: string;
  faq: [string, string][];
}

const page = (p: RailingPage): ProfileCategory => {
  if (p.models.length !== 6 || p.faq.length !== 8) throw new Error(`railing RU page ${p.slug}: expected 6 models and 8 own FAQs`);
  return {
    ...p,
    group: 'railings',
    path: p.path ?? P(p.slug),
    eyebrow: `Стеклянные ограждения / ${p.eyebrow}`,
    heroImage: `hero-${p.slug}`,
    imageBase: RAILINGS_IMG,
    process: PROCESS,
    compareColumns: COMPARE,
    faq: [...p.faq, ...COMMON],
    catalogButton: 'Смотреть варианты',
    optionsLabel: 'Вариант',
    catalogNote: 'Параметры приведены для типовых конфигураций. Толщину стекла, шаг креплений и высоту определяем после замера с учётом основания и нагрузки. Ориентировочную стоимость можно посчитать в конфигураторе.',
    heroExtra: ['Рассчитать в конфигураторе', RAILINGS_CONFIGURATOR]
  };
};

